(function(){'use strict';
var KEY='welog-direct-split-bounds-v4';
function read(){try{var b=JSON.parse(localStorage.getItem(KEY)||'{}')||{};return{top:+b.top||0,right:+b.right||0,bottom:+b.bottom||0,left:+b.left||0}}catch(e){return{top:0,right:0,bottom:0,left:0}}}
function split(){return document.querySelector('#sheet .center .pair-split')}
function rect(){var s=split();if(!s)return null;var r=s.getBoundingClientRect(),b=read();return{left:r.left+b.left,top:r.top+b.top,right:r.right-b.right,bottom:r.bottom-b.bottom,base:r}}
function syncBackground(){var s=split();if(!s)return;var r=s.getBoundingClientRect(),b=read();if(!r.width||!r.height)return;var top=Math.max(0,b.top/r.height*100),bottom=Math.max(0,b.bottom/r.height*100),left=Math.max(0,b.left/r.width*200),right=Math.max(0,b.right/r.width*200);s.style.setProperty('--welog-bound-top',top+'%');s.style.setProperty('--welog-bound-bottom',bottom+'%');s.style.setProperty('--welog-bound-left-cell',left+'%');s.style.setProperty('--welog-bound-right-cell',right+'%');var cells=s.querySelectorAll('.pair-image');cells.forEach(function(c){var bg=getComputedStyle(c).backgroundColor;if(bg&&bg!=='rgba(0, 0, 0, 0)'&&bg!=='transparent')c.style.setProperty('--welog-cell-bg',bg);c.classList.add('welog-bound-bg-cell')})}
function syncSelection(){var box=document.querySelector('.welog-layout-box-fixed'),label=box&&box.querySelector('span');if(!box||!label||label.textContent.indexOf('중앙 그림')!==0)return;var r=rect();if(!r)return;box.style.left=r.left+'px';box.style.top=r.top+'px';box.style.width=Math.max(30,r.right-r.left)+'px';box.style.height=Math.max(30,r.bottom-r.top)+'px'}
function sync(){syncBackground();requestAnimationFrame(syncSelection)}
window.addEventListener('welog-influence-bounds-change',sync);window.addEventListener('resize',sync,{passive:true});window.addEventListener('scroll',sync,true);document.addEventListener('pointerdown',function(){setTimeout(sync,0)},true);document.addEventListener('click',function(){setTimeout(sync,20)},true);document.addEventListener('input',function(){setTimeout(sync,20)},true);document.addEventListener('change',function(){setTimeout(sync,20)},true);if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',sync);else sync();
})();